Here is the root cause:
The net_device is allocated during function instance creation and registered during bind with the gadget device as its sysfs parent. However, when the function unbinds, the parent gadget device is destroyed while the net_device remains registered, leaving a dangling sysfs symlink. The lifecycle did not reparent the net_device away from the dying gadget device, nor did it track multiple bindings to prevent double registration/detachment.

Here is the patch:

 static int
 ecm_bind(struct usb_configuration *c, struct usb_function *f)
 {
 	struct usb_composite_dev *cdev = c->cdev;
 	struct f_ecm		*ecm = func_to_ecm(f);
 	struct usb_string	*us;
 	int			status = 0;
 	struct usb_ep		*ep;

 	struct f_ecm_opts	*ecm_opts;
+	struct net_device	*net __free(detach_gadget) = NULL;
 	struct usb_request	*request __free(free_usb_request) = NULL;

 	if (!can_support_ecm(cdev->gadget))
 		return -EINVAL;

 	ecm_opts = container_of(f->fi, struct f_ecm_opts, func_inst);

-	mutex_lock(&ecm_opts->lock);
-
-	gether_set_gadget(ecm_opts->net, cdev->gadget);
-
-	if (!ecm_opts->bound) {
-		status = gether_register_netdev(ecm_opts->net);
-		ecm_opts->bound = true;
-	}
-
-	mutex_unlock(&ecm_opts->lock);
-	if (status)
-		return status;
+	scoped_guard(mutex, &ecm_opts->lock)
